rednet.open("right") -- Modem en el lado derecho (ajustar según ubicación)motor = peripheral.wrap("back") -- Motor traserohelices = peripheral.wrap("top") -- Hélices arribaprint("Helicóptero esperando comandos...")while true do    senderID, message = rednet.receive() -- Recibe datos de la base    if mq" motor.setYaw(5)    elseif message == "subir" then        helices.setSpeed(40)    elseif message == "bajar" then        helices.setSpeed(20)    elseif message == "detener" then        motor.setThrust(0)        motor.setYaw(0)    endend
